// Generated by `tsir make:job`. Verifies the job is declared with the right
// name and that its handler runs without throwing.
import { describe, expect, test } from 'bun:test';

import { SendWelcomeEmailJob } from './send-welcome-email.job.ts';

describe('SendWelcomeEmailJob', () => {
  test('is declared with the expected name', () => {
    expect(SendWelcomeEmailJob.name).toBe('send-welcome-email');
  });

  test('handler runs without throwing', () => {
    // A minimal context matching what the worker passes in.
    const context = {
      id: 'job-1',
      name: 'send-welcome-email',
      connection: 'memory',
      payload: { id: 'u_1' },
      attempt: 1,
      maxAttempts: 5,
      signal: new AbortController().signal,
      log: () => undefined,
    };
    expect(() => SendWelcomeEmailJob.handle(context as never)).not.toThrow();
  });
});
